program.reduce:
const v = row.vendor_name || '(No vendor)';
const amt = Number(row._amount_inr) || 0;
state.totalCount++;
state.grandTotalINR += amt;
if (!state.vendors[v]) state.vendors[v] = {count:0,total:0};
state.vendors[v].count++;
state.vendors[v].total += amt;
return state;

program.finalize:
const sorted = Object.entries(state.vendors)
  .map(([vendor, d]) => ({vendor, count:d.count, totalINR:d.total}))
  .sort((a,b) => b.totalINR - a.totalINR);
return {
  totalCount: state.totalCount,
  grandTotalINR: state.grandTotalINR,
  topFive: sorted.slice(0,5)
};
